FUNCTION_BLOCK FB_Com
VAR_INPUT
    txReq  : BOOL; (* Solicitud de inicio de intercambio *)
    rxOk   : BOOL; (* Confirmacion recibida del dispositivo externo *)
    rxData : INT;  (* Dato recibido (eco esperado) *)
END_VAR
VAR_OUTPUT
    txData   : INT;  (* Dato transmitido al dispositivo externo *)
    ocupado  : BOOL; (* TRUE mientras hay un intercambio en curso *)
    ok       : BOOL; (* TRUE si el intercambio termino correctamente *)
    error    : BOOL; (* TRUE si fallaron los 3 intentos *)
    nIntentos: INT;  (* Numero del intento en curso o ultimo realizado *)
END_VAR
VAR
    tIntento  : TON;       (* Temporizador de plazo por intento (500 ms) *)
    txReqPrev : BOOL;      (* Valor anterior de txReq para detectar flanco *)
    enCurso   : BOOL;      (* Intercambio activo internamente *)
    VAL_PRUEBA: INT := 100;(* Valor fijo de prueba transmitido *)
END_VAR

(* --- Deteccion de flanco ascendente en txReq --- *)
IF txReq AND NOT txReqPrev THEN
    IF NOT enCurso THEN
        (* Iniciar nuevo intercambio *)
        enCurso   := TRUE;
        ocupado   := TRUE;
        ok        := FALSE;
        error     := FALSE;
        nIntentos := 1;
        txData    := VAL_PRUEBA;
        (* Arrancar temporizador del primer intento *)
        tIntento(IN := FALSE, PT := T#500MS); (* Reset previo *)
    END_IF;
END_IF;
txReqPrev := txReq;

(* --- Logica principal del intercambio --- *)
IF enCurso THEN
    (* Mantener temporizador activo *)
    tIntento(IN := TRUE, PT := T#500MS);

    (* Comprobar respuesta correcta: rxOk activo y eco coincide *)
    IF rxOk AND (rxData = txData) THEN
        (* Intento exitoso *)
        ok        := TRUE;
        ocupado   := FALSE;
        enCurso   := FALSE;
        tIntento(IN := FALSE, PT := T#500MS); (* Detener temporizador *)

    (* Comprobar fallo: plazo vencido O rxOk con dato incorrecto *)
    ELSIF tIntento.Q OR (rxOk AND (rxData <> txData)) THEN
        (* Detener temporizador antes de evaluar siguiente paso *)
        tIntento(IN := FALSE, PT := T#500MS);

        IF nIntentos >= 3 THEN
            (* Agotados los 3 intentos *)
            error   := TRUE;
            ocupado := FALSE;
            enCurso := FALSE;
        ELSE
            (* Iniciar siguiente intento *)
            nIntentos := nIntentos + 1;
            (* El temporizador se reanudara en el proximo ciclo con IN=TRUE *)
        END_IF;
    END_IF;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Com

VAR_INPUT
    txReq  : BOOL; (* Solicitud de transmisión *)
    rxOk   : BOOL; (* Confirmación de recepción del dispositivo externo *)
    rxData : INT;  (* Dato recibido (eco) *)
END_VAR

VAR_OUTPUT
    txData   : INT;  (* Dato transmitido *)
    ocupado  : BOOL; (* Intercambio en curso *)
    ok       : BOOL; (* Último intercambio correcto *)
    error    : BOOL; (* Fallaron los 3 intentos *)
    nIntentos: INT;  (* Número de intento en curso / último *)
END_VAR

VAR
    txReq_prev : BOOL;        (* Valor anterior de txReq para detectar flanco *)
    timer      : TON;         (* Temporizador de 500 ms por intento *)
    timerStart : BOOL;        (* Señal de arranque del temporizador *)
    TEST_VALUE : INT := 100;  (* Valor de prueba fijo *)
    MAX_INTENTOS : INT := 3;  (* Máximo de intentos permitidos *)
END_VAR

(* ─────────────────────────────────────────────────────────────
   Detección de flanco ascendente en txReq
   ───────────────────────────────────────────────────────────── *)
IF txReq AND NOT txReq_prev THEN
    (* Flanco detectado: iniciar intercambio solo si no hay uno en curso *)
    IF NOT ocupado THEN
        ocupado   := TRUE;
        ok        := FALSE;
        error     := FALSE;
        nIntentos := 1;
        txData    := TEST_VALUE;
        timerStart := FALSE; (* Forzar reinicio del TON en el siguiente ciclo *)
    END_IF;
END_IF;
txReq_prev := txReq;

(* ─────────────────────────────────────────────────────────────
   Lógica principal: solo activa cuando hay intercambio en curso
   ───────────────────────────────────────────────────────────── *)
IF ocupado THEN

    (* Arrancar / mantener el temporizador del intento actual *)
    timerStart := TRUE;
    timer(IN := timerStart, PT := T#500MS);

    (* Comprobar respuesta correcta: rxOk activo y eco coincide *)
    IF rxOk AND (rxData = txData) THEN
        (* Intento exitoso *)
        ok        := TRUE;
        ocupado   := FALSE;
        timerStart := FALSE;
        timer(IN := FALSE, PT := T#500MS); (* Detener temporizador *)

    (* Comprobar fallo: tiempo agotado O rxOk con dato incorrecto *)
    ELSIF timer.Q OR (rxOk AND (rxData <> txData)) THEN
        (* Intento fallido *)
        IF nIntentos < MAX_INTENTOS THEN
            (* Iniciar siguiente intento *)
            nIntentos  := nIntentos + 1;
            timerStart := FALSE;             (* Bajar IN para reiniciar TON *)
            timer(IN := FALSE, PT := T#500MS);
            (* timerStart se volverá TRUE en el próximo ciclo *)
        ELSE
            (* Se agotaron los 3 intentos *)
            error      := TRUE;
            ocupado    := FALSE;
            timerStart := FALSE;
            timer(IN := FALSE, PT := T#500MS); (* Detener temporizador *)
        END_IF;
    END_IF;

END_IF;

(* Llamada final al temporizador para actualizar su salida Q *)
timer(IN := timerStart, PT := T#500MS);

FUNCTION_BLOCK FB_Com
VAR_INPUT
    txReq : BOOL;  (* Peticion de transmision *)
    rxOk : BOOL;   (* Confirmacion de recepcion *)
    rxData : INT;  (* Datos recibidos (eco) *)
END_VAR
VAR_OUTPUT
    txData : INT;  (* Datos a transmitir *)
    ocupado : BOOL;(* Intercambio en curso *)
    ok : BOOL;     (* Intercambio correcto *)
    error : BOOL;  (* Intercambio fallido tras 3 intentos *)
    nIntentos : INT; (* Numero de intento actual *)
END_VAR
VAR
    flancoReq : R_TRIG; (* Detector de flanco para txReq *)
    flancoRx : R_TRIG;  (* Detector de flanco para rxOk *)
    temporizador : TON; (* Temporizador de 500 ms *)
    resetTemp : BOOL;   (* Señal para reiniciar el temporizador *)
END_VAR

(* Deteccion de flancos *)
flancoReq(CLK := txReq);
flancoRx(CLK := rxOk);

(* Inicio de un nuevo intercambio si no esta ocupado *)
IF flancoReq.Q AND NOT ocupado THEN
    ocupado := TRUE;
    ok := FALSE;
    error := FALSE;
    nIntentos := 1;
    txData := 100;
    resetTemp := TRUE;
ELSE
    resetTemp := FALSE;
END_IF;

(* Temporizador del intento en curso (se reinicia con resetTemp) *)
temporizador(IN := ocupado AND NOT resetTemp, PT := T#500MS);

(* Logica durante el intercambio *)
IF ocupado THEN
    (* Evaluacion de la respuesta *)
    IF flancoRx.Q THEN
        IF rxData = txData THEN
            (* Respuesta correcta (eco valido) *)
            ok := TRUE;
            ocupado := FALSE;
        ELSE
            (* Respuesta incorrecta: falla el intento *)
            IF nIntentos < 3 THEN
                nIntentos := nIntentos + 1;
                resetTemp := TRUE;
            ELSE
                error := TRUE;
                ocupado := FALSE;
            END_IF;
        END_IF;
    (* Evaluacion del timeout *)
    ELSIF temporizador.Q THEN
        IF nIntentos < 3 THEN
            nIntentos := nIntentos + 1;
            resetTemp := TRUE;
        ELSE
            error := TRUE;
            ocupado := FALSE;
        END_IF;
    END_IF;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Com
VAR
    // Entradas
    txReq : BOOL;
    rxOk : BOOL;
    rxData : INT;

    // Salidas
    txData : INT;
    ocupado : BOOL;
    ok : BOOL;
    error : BOOL;
    nIntentos : INT;

    // Variables internas
    txReqPrev : BOOL; // Para detectar flancos
    intentoActual : INT; // Contador de intentos
    timer : TON; // Temporizador para los 500 ms
    intentoExitoso : BOOL; // Indica si el intento fue exitoso
END_VAR

// Inicialización de variables
IF NOT ocupado THEN
    txData := 100; // Valor de prueba
    intentoActual := 0;
    intentoExitoso := FALSE;
    ok := FALSE;
    error := FALSE;
END_IF

// Detección de flanco ascendente en txReq
IF txReq AND NOT txReqPrev THEN
    IF NOT ocupado THEN
        // Iniciar nuevo intercambio
        ocupado := TRUE;
        intentoActual := 1;
        nIntentos := intentoActual;
        timer(IN := TRUE, PT := T#500MS);
    END_IF
END_IF

// Guardar estado anterior de txReq
txReqPrev := txReq;

// Lógica de intercambio
IF ocupado THEN
    // Verificar si el temporizador ha expirado
    timer(IN := TRUE);
    IF timer.Q THEN
        // Intento fallido, incrementar contador de intentos
        intentoActual := intentoActual + 1;
        IF intentoActual > 3 THEN
            // Todos los intentos fallaron
            error := TRUE;
            ocupado := FALSE;
        ELSE
            // Iniciar nuevo intento
            nIntentos := intentoActual;
            timer(IN := TRUE, PT := T#500MS);
        END_IF
    ELSE
        // Verificar si el intento es exitoso
        IF rxOk AND (rxData = txData) THEN
            intentoExitoso := TRUE;
            ok := TRUE;
            ocupado := FALSE;
        END_IF
    END_IF
END_IF

FUNCTION_BLOCK FB_Com
VAR_INPUT
    txReq  : BOOL; (* Solicitud de transmisión *)
    rxOk   : BOOL; (* Confirmación de recepción del dispositivo externo *)
    rxData : INT;  (* Dato recibido (eco) *)
END_VAR

VAR_OUTPUT
    txData   : INT;  (* Dato transmitido *)
    ocupado  : BOOL; (* Intercambio en curso *)
    ok       : BOOL; (* Último intercambio exitoso *)
    error    : BOOL; (* Fallaron los 3 intentos *)
    nIntentos: INT;  (* Número de intento en curso / último *)
END_VAR

VAR
    txReq_prev : BOOL;        (* Valor anterior de txReq para detectar flanco *)
    timer      : TON;         (* Temporizador de plazo por intento *)
    timerRun   : BOOL;        (* Habilita el temporizador *)
    TEST_VALUE : INT := 100;  (* Valor de prueba fijo *)
    MAX_INT    : INT := 3;    (* Máximo número de intentos *)
END_VAR

(* ── Temporizador ── *)
timer(IN := timerRun, PT := T#500MS);

(* ── Detección de flanco ascendente en txReq ── *)
IF txReq AND NOT txReq_prev THEN
    IF NOT ocupado THEN
        (* Iniciar nuevo intercambio *)
        ok        := FALSE;
        error     := FALSE;
        ocupado   := TRUE;
        nIntentos := 1;
        txData    := TEST_VALUE;
        timerRun  := TRUE;   (* Arrancar temporizador del intento 1 *)
    END_IF;
    (* Si ocupado = TRUE, el flanco se ignora *)
END_IF;

(* ── Lógica principal durante un intercambio ── *)
IF ocupado THEN

    IF rxOk THEN
        (* Ha llegado respuesta del dispositivo *)
        IF rxData = txData THEN
            (* ── Intento correcto ── *)
            timerRun := FALSE;
            ocupado  := FALSE;
            ok       := TRUE;
        ELSE
            (* ── Respuesta incorrecta: tratar como fallo de intento ── *)
            timerRun := FALSE;          (* Detener y resetear temporizador *)
            IF nIntentos < MAX_INT THEN
                nIntentos := nIntentos + 1;
                timerRun  := TRUE;      (* Nuevo plazo para el siguiente intento *)
            ELSE
                (* Agotados los 3 intentos *)
                ocupado := FALSE;
                error   := TRUE;
            END_IF;
        END_IF;

    ELSIF timer.Q THEN
        (* ── Plazo vencido sin confirmación ── *)
        timerRun := FALSE;              (* Resetear temporizador *)
        IF nIntentos < MAX_INT THEN
            nIntentos := nIntentos + 1;
            timerRun  := TRUE;          (* Nuevo plazo para el siguiente intento *)
        ELSE
            (* Agotados los 3 intentos *)
            ocupado := FALSE;
            error   := TRUE;
        END_IF;
    END_IF;

END_IF;

(* ── Guardar estado anterior de txReq ── *)
txReq_prev := txReq;

FUNCTION_BLOCK FB_Com
VAR_INPUT
    txReq : BOOL;   (* Peticion de transmision *)
    rxOk : BOOL;    (* Confirmacion de recepcion *)
    rxData : INT;   (* Dato recibido (eco) *)
END_VAR
VAR_OUTPUT
    txData : INT;   (* Dato a transmitir *)
    ocupado : BOOL; (* Intercambio en curso *)
    ok : BOOL;      (* Intercambio correcto *)
    error : BOOL;   (* Intercambio fallido tras 3 intentos *)
    nIntentos : INT;(* Numero de intento actual *)
END_VAR
VAR
    rTrigReq : R_TRIG; (* Detector de flanco para txReq *)
    rTrigRx : R_TRIG;  (* Detector de flanco para rxOk *)
    tTimeout : TON;    (* Temporizador de 500 ms *)
END_VAR

(* Deteccion de flancos *)
rTrigReq(CLK := txReq);
rTrigRx(CLK := rxOk);

(* Inicio de un nuevo intercambio si no hay uno en curso *)
IF rTrigReq.Q AND NOT ocupado THEN
    txData := 100;
    ocupado := TRUE;
    ok := FALSE;
    error := FALSE;
    nIntentos := 1;
    tTimeout(IN := FALSE, PT := T#500MS); (* Asegura el reinicio del temporizador *)
END_IF;

(* Control del intercambio en curso *)
IF ocupado THEN
    (* Actualiza el temporizador del intento actual *)
    tTimeout(IN := TRUE, PT := T#500MS);

    (* Evaluacion de la respuesta *)
    IF rTrigRx.Q AND (rxData = txData) THEN
        (* Intento correcto *)
        ok := TRUE;
        ocupado := FALSE;
        tTimeout(IN := FALSE, PT := T#500MS);

    ELSIF tTimeout.Q OR (rTrigRx.Q AND (rxData <> txData)) THEN
        (* Intento fallido por timeout o dato incorrecto *)
        IF nIntentos < 3 THEN
            (* Pasa al siguiente intento *)
            nIntentos := nIntentos + 1;
            tTimeout(IN := FALSE, PT := T#500MS); (* Reinicia el tiempo para el nuevo intento *)
        ELSE
            (* Fallaron los 3 intentos *)
            error := TRUE;
            ocupado := FALSE;
            tTimeout(IN := FALSE, PT := T#500MS);
        END_IF;
    END_IF;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Com
VAR_INPUT
    txReq : BOOL;   // Petición de transmisión
    rxOk : BOOL;    // Confirmación de recepción
    rxData : INT;   // Dato recibido
END_VAR

VAR_OUTPUT
    txData : INT;   // Dato a transmitir
    ocupado : BOOL; // Intercambio en curso
    ok : BOOL;      // Intercambio exitoso
    error : BOOL;   // Intercambio fallido tras 3 intentos
    nIntentos : INT;// Número de intento actual (1, 2 o 3)
END_VAR

VAR
    rtTxReq : R_TRIG; // Detector de flanco para txReq
    rtRxOk : R_TRIG;  // Detector de flanco para rxOk
    timer : TON;      // Temporizador de 500ms
    timerIn : BOOL;   // Control de inicio/reinicio del temporizador
END_VAR

// Detección de flancos ascendentes
rtTxReq(CLK := txReq);
rtRxOk(CLK := rxOk);

// Inicio de un nuevo intercambio (se ignora si ya está ocupado)
IF rtTxReq.Q AND NOT ocupado THEN
    txData := 100;
    ocupado := TRUE;
    ok := FALSE;
    error := FALSE;
    nIntentos := 1;
    timerIn := FALSE; // Fuerza un ciclo en FALSE para reiniciar el temporizador
END_IF;

// Actualización del temporizador
timer(IN := timerIn, PT := T#500MS);

// Máquina de estados durante el intercambio
IF ocupado THEN
    IF timerIn THEN
        // El temporizador está corriendo, evaluar condiciones de respuesta o timeout
        IF rtRxOk.Q AND (rxData = txData) THEN
            // Éxito: se recibió confirmación con el eco correcto
            ok := TRUE;
            ocupado := FALSE;
            timerIn := FALSE;

        ELSIF timer.Q OR (rtRxOk.Q AND (rxData <> txData)) THEN
            // Falla: por tiempo agotado o por dato incorrecto
            IF nIntentos < 3 THEN
                nIntentos := nIntentos + 1;
                timerIn := FALSE; // Reinicia el temporizador en el próximo ciclo
            ELSE
                // Fallaron los 3 intentos permitidos
                error := TRUE;
                ocupado := FALSE;
                timerIn := FALSE;
            END_IF;
        END_IF;
    ELSE
        // Activar el temporizador para iniciar el conteo del intento actual
        timerIn := TRUE;
    END_IF;
ELSE
    // Asegurar que el temporizador se mantenga apagado si no hay intercambio activo
    timerIn := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Com
VAR_INPUT
    txReq : BOOL; (* Solicitud de transmisión *)
    rxOk : BOOL; (* Confirmación de recepción *)
    rxData : INT; (* Datos recibidos *)
END_VAR
VAR_OUTPUT
    txData : INT; (* Datos a transmitir *)
    ocupado : BOOL; (* Indica si el intercambio está en curso *)
    ok : BOOL; (* Indica si el intercambio fue exitoso *)
    error : BOOL; (* Indica si el intercambio falló *)
    nIntentos : INT; (* Número de intento actual *)
END_VAR
VAR
    intentoActual : INT := 0; (* Contador de intentos *)
    valorPrueba : INT := 100; (* Valor de prueba a transmitir *)
    tLimite : TON; (* Temporizador de límite de tiempo *)
    txReqAnt : BOOL := FALSE; (* Estado anterior de txReq *)
    intercambioEnCurso : BOOL := FALSE; (* Estado del intercambio *)
END_VAR

(* Detectar flanco ascendente de txReq *)
IF txReq AND NOT txReqAnt THEN
    IF NOT intercambioEnCurso THEN
        (* Iniciar nuevo intercambio *)
        txData := valorPrueba;
        ocupado := TRUE;
        ok := FALSE;
        error := FALSE;
        intentoActual := 1;
        intercambioEnCurso := TRUE;
        tLimite(IN := TRUE, PT := T#500MS);
    END_IF;
END_IF;

(* Control de intentos y recepción *)
IF intercambioEnCurso THEN
    IF tLimite.Q THEN
        (* Tiempo límite alcanzado, intento fallido *)
        intentoActual := intentoActual + 1;
        IF intentoActual > 3 THEN
            (* Todos los intentos fallaron *)
            error := TRUE;
            ocupado := FALSE;
            intercambioEnCurso := FALSE;
        ELSE
            (* Iniciar nuevo intento *)
            tLimite(IN := TRUE, PT := T#500MS);
        END_IF;
    ELSIF rxOk AND (rxData = valorPrueba) THEN
        (* Intento exitoso *)
        ok := TRUE;
        ocupado := FALSE;
        intercambioEnCurso := FALSE;
    END_IF;
END_IF;

(* Actualizar salidas *)
nIntentos := intentoActual;

(* Almacenar estado anterior de txReq *)
txReqAnt := txReq;
END_FUNCTION_BLOCK

