// Inicialización del temporizador
timer(IN := FALSE, PT := T#500MS);

// Máquina de estados
CASE estado OF
    0: // Estado Idle
        IF txReq AND NOT inicioIntercambio THEN
            inicioIntercambio := TRUE;
            estado := 1;
            intentos := 1;
            nIntentos := intentos;
            valorTx := 100;
            txData := valorTx;
            ocupado := TRUE;
            timer(IN := TRUE);
        END_IF

