        IF rxOk AND (rxData = valorTx) THEN
            estado := 0;
            ok := TRUE;
            ocupado := FALSE;
            inicioIntercambio := FALSE;
        ELSIF timer.Q THEN
            IF intentos < 3 THEN
                intentos := intentos + 1;
                nIntentos := intentos;
