END_VAR

VAR
    txReq_prev : BOOL;       (* Valor anterior de txReq para detectar flanco ascendente *)
    timer      : TON;        (* Temporizador de plazo por intento *)
    activo     : BOOL;       (* Intercambio en curso internamente *)
    valorTx    : INT := 100; (* Valor de prueba fijo *)
END_VAR

(* ── Detección de flanco ascendente de txReq ── *)
IF txReq AND NOT txReq_prev THEN
    IF NOT activo THEN
        (* Iniciar nuevo intercambio *)
        activo    := TRUE;
        ocupado   := TRUE;
        ok        := FALSE;
        error     := FALSE;
        nIntentos := 1;
        txData    := valorTx;
        (* Arrancar temporizador del primer intento *)
        timer(IN := FALSE, PT := T#500MS);
        timer(IN := TRUE,  PT := T#500MS);
    END_IF;
    (* Si activo = TRUE, el flanco se ignora *)
END_IF;

(* ── Lógica principal del intercambio ── *)
IF activo THEN
    (* Actualizar temporizador *)
    timer(IN := TRUE, PT := T#500MS);

    (* Comprobar respuesta correcta: rxOk activo y eco coincide *)
    IF rxOk AND (rxData = txData) THEN
        (* Intento exitoso *)
        ok      := TRUE;
        error   := FALSE;
        ocupado := FALSE;
        activo  := FALSE;
        timer(IN := FALSE, PT := T#500MS); (* Detener temporizador *)

    (* Comprobar fallo: plazo vencido O rxOk con dato incorrecto *)
    ELSIF timer.Q OR (rxOk AND (rxData <> txData)) THEN
        (* Intento fallido *)
        timer(IN := FALSE, PT := T#500MS); (* Resetear temporizador *)

        IF nIntentos < 3 THEN
            (* Iniciar siguiente intento *)
            nIntentos := nIntentos + 1;
            txData    := valorTx;
            timer(IN := TRUE, PT := T#500MS); (* Arrancar nuevo plazo *)
        ELSE
            (* Agotados los 3 intentos *)
            error   := TRUE;
            ok      := FALSE;
            ocupado := FALSE;
            activo  := FALSE;
        END_IF;
    END_IF;
END_IF;

(* ── Guardar estado anterior de txReq ── *)
txReq_prev := txReq;

FUNCTION_BLOCK FB_Com
VAR_INPUT
    txReq : BOOL;
    rxOk : BOOL;
    rxData : INT;
END_VAR
VAR_OUTPUT
    txData : INT;
    ocupado : BOOL;
    ok : BOOL;
    error : BOOL;
    nIntentos : INT;
END_VAR
VAR
    txReq_Trig : R_TRIG;
    rxOk_Trig : R_TRIG;
    temporizador : TON;
    estado : INT := 0; // 0: Reposo, 1: Intercambio en curso
END_VAR

// Detección de flancos ascendentes
txReq_Trig(CLK := txReq);
rxOk_Trig(CLK := rxOk);

// Actualización del temporizador
temporizador(IN := (estado = 1), PT := T#500MS);

CASE estado OF
    0: // Reposo: esperando nueva petición
        IF txReq_Trig.Q THEN
            txData := 100;
            ocupado := TRUE;
            ok := FALSE;
            error := FALSE;
            nIntentos := 1;
            estado := 1;

            // Reinicio forzado del temporizador para el intento 1
            temporizador(IN := FALSE);
            temporizador(IN := TRUE, PT := T#500MS);
        END_IF;

    1: // Intercambio en curso: esperando respuesta o timeout
        IF rxOk_Trig.Q THEN
            IF rxData = txData THEN
                // Éxito: confirmación recibida con eco correcto
                ok := TRUE;
                ocupado := FALSE;
                estado := 0;
            ELSE
                // Fallo: confirmación recibida pero dato incorrecto
                nIntentos := nIntentos + 1;
                temporizador(IN := FALSE);
                temporizador(IN := TRUE, PT := T#500MS);
            END_IF;
        ELSIF temporizador.Q THEN
            // Fallo: vencimiento del plazo de 500 ms sin confirmación
            nIntentos := nIntentos + 1;
            temporizador(IN := FALSE);
            temporizador(IN := TRUE, PT := T#500MS);
        END_IF;

        // Evaluación del límite máximo de intentos
        IF estado = 1 AND nIntentos > 3 THEN
            error := TRUE;
            ocupado := FALSE;
            nIntentos := 3; // Conserva el último valor válido
            estado := 0;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK

