IF txReq AND NOT ocupado THEN
    estado := 1;
    intentos := 1;
    txData := 100;
    ocupado := TRUE;
    tEspera(IN := TRUE, PT := T#500MS);
END_IF

IF estado = 1 THEN
    IF tEspera.Q THEN
        IF rxOk AND rxData = txData THEN
            estado := 2;
            ok := TRUE;
        ELSE
            estado := 3;
            error := TRUE;
        END_IF
        ocupado := FALSE;
    END_IF
END_IF

IF estado = 3 AND intentos < 3 THEN
    estado := 1;
    intentos := intentos + 1;
    tEspera(IN := TRUE, PT := T#500MS);
END_IF

nIntentos := intentos;

IF estado = 2 THEN
    ocupado := FALSE;
    ok := TRUE;
END_IF

IF estado = 3 AND intentos = 3 THEN
    ocupado := FALSE;
    error := TRUE;
END_IF

END_FUNCTION_BLOCK

