        activo   := FALSE;
        tTimeout(IN := FALSE, PT := T#500MS); (* Detener temporizador *)

    (* Verificar fallo: plazo vencido o eco incorrecto *)
    ELSIF tTimeout.Q OR (rxOk AND (rxData <> txValor)) THEN
        tTimeout(IN := FALSE, PT := T#500MS); (* Reset del temporizador *)

        IF nIntentos < 3 THEN
            (* Iniciar siguiente intento *)
            nIntentos := nIntentos + 1;
            (* El temporizador arrancara en el proximo ciclo con IN=TRUE *)
        ELSE
            (* Agotados los 3 intentos: error *)
            error   := TRUE;
            ocupado := FALSE;
            activo  := FALSE;
        END_IF;
    END_IF;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Com
VAR_INPUT
    txReq : BOOL; (* Solicitud de transmision *)
    rxOk : BOOL; (* Confirmacion de recepcion *)
    rxData : INT; (* Datos recibidos *)
END_VAR
VAR_OUTPUT
    txData : INT; (* Datos a transmitir *)
    ocupado : BOOL; (* Indicador de intercambio en curso *)
    ok : BOOL; (* Indicador de intercambio exitoso *)
    error : BOOL; (* Indicador de error en el intercambio *)
    nIntentos : INT; (* Numero de intento actual *)
END_VAR
VAR
    txReqPrev : BOOL; (* Estado previo de txReq *)
    intentoActual : INT; (* Contador de intentos *)
    tTimeout : TON; (* Temporizador de timeout *)
    intercambioActivo : BOOL; (* Indicador de intercambio activo *)
END_VAR

(* Inicializacion de variables *)
IF NOT intercambioActivo THEN
    IF txReq AND NOT txReqPrev THEN
        (* Inicio de un nuevo intercambio *)
        txData := 100;
        ocupado := TRUE;
        ok := FALSE;
        error := FALSE;
        intentoActual := 1;
        nIntentos := intentoActual;
        intercambioActivo := TRUE;
        tTimeout(IN := TRUE, PT := T#500MS);
    END_IF;
ELSE
    (* Proceso de intercambio en curso *)
    IF tTimeout.Q THEN
        (* Timeout del intento actual *)
        intentoActual := intentoActual + 1;
        IF intentoActual > 3 THEN
            (* Todos los intentos fallaron *)
            error := TRUE;
            ocupado := FALSE;
            intercambioActivo := FALSE;
        ELSE
            (* Iniciar siguiente intento *)
            nIntentos := intentoActual;
            tTimeout(IN := TRUE, PT := T#500MS);
        END_IF;
    ELSIF rxOk AND (rxData = txData) THEN
        (* Intento exitoso *)
        ok := TRUE;
        ocupado := FALSE;
        intercambioActivo := FALSE;
    END_IF;
END_IF;

(* Actualizar estado previo de txReq *)
txReqPrev := txReq;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Com
VAR_INPUT
    txReq : BOOL; (* Petición de transmisión *)
    rxOk : BOOL; (* Confirmación de recepción *)
    rxData : INT; (* Datos recibidos *)
END_VAR
VAR_OUTPUT
    txData : INT; (* Datos a transmitir *)
    ocupado : BOOL; (* Estado de ocupado *)
    ok : BOOL; (* Confirmación de éxito *)
    error : BOOL; (* Confirmación de error *)
    nIntentos : INT; (* Número de intentos *)
END_VAR
VAR
    tEspera : TP; (* Temporizador de espera *)
    estado : INT; (* Estado actual del intercambio *)
    intentos : INT; (* Contador de intentos *)
END_VAR

(* Estados: 0 = Inactivo, 1 = En espera de respuesta, 2 = Éxito, 3 = Error *)
IF txReq AND NOT ocupado THEN
    estado := 1;
    intentos := 1;
    txData := 100;
    ocupado := TRUE;
    tEspera(IN := TRUE, PT := T#500MS);
END_IF

CASE estado OF
    1: (* Esperando respuesta *)
        IF tEspera.Q THEN
            IF rxOk AND rxData = txData THEN
                estado := 2;
                ok := TRUE;
                ocupado := FALSE;
            ELSE
                intentos := intentos + 1;
                IF intentos > 3 THEN
                    estado := 3;
                    error := TRUE;
                    ocupado := FALSE;
                ELSE
                    tEspera(IN := TRUE, PT := T#500MS);
                END_IF;
            END_IF;
        END_IF;
    2: (* Éxito *)
        (* Mantener ok activo hasta el siguiente intercambio *)
    3: (* Error *)
        (* Mantener error activo hasta el siguiente intercambio *)
END_CASE;

nIntentos := intentos;
END_FUNCTION_BLOCK
